delete from public.customer_access where user_id='00000000-0000-4000-8000-000000000004';
update auth.sessions set aal='aal2' where user_id='00000000-0000-4000-8000-000000000004';
insert into private.platform_administrators(user_id) values('00000000-0000-4000-8000-000000000004');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000004","session_id":"10000000-0000-4000-8000-000000000004","aal":"aal2"}',true);
select pg_temp.assert_true(jsonb_array_length(public.platform_owner_accounts())=2,'platform admin lists owner accounts');
select pg_temp.assert_true((select count(*)=0 from public.customers),'platform role grants no customer access');
select pg_temp.assert_true((select count(*)=0 from public.properties),'platform role grants no addresses');
select pg_temp.assert_true((select count(*)=0 from public.invoices),'platform role grants no invoice access');
select pg_temp.assert_true((select count(*)=0 from public.memberships),'platform role does not create tenant membership');
select pg_temp.assert_true(not (public.platform_owner_accounts()->0 ? 'customers'),'owner account result has no customer data');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
do $$begin begin perform public.platform_owner_accounts();raise exception 'TEST FAILED owner gets platform admin';exception when insufficient_privilege then null;end;end$$;
reset role;
update private.platform_administrators set revoked_at=now();
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000004","session_id":"10000000-0000-4000-8000-000000000004","aal":"aal2"}',true);
do $$begin begin perform public.platform_owner_accounts();raise exception 'TEST FAILED revoked platform admin';exception when insufficient_privilege then null;end;end$$;
reset role;rollback;
